// Home Screen app: manifest, icons and the head tags iOS / Android read when the site is
// added to the Home Screen. Icons are generated by scripts/icons/build.py.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(resolve(root, p), 'utf8');
const html = read('index.html');
const manifest = JSON.parse(read('public/manifest.webmanifest'));

/** Width, height and colour type from a PNG's IHDR chunk. */
function pngInfo(path) {
  const b = readFileSync(resolve(root, path));
  assert.equal(b.toString('latin1', 1, 4), 'PNG', `${path} is not a PNG`);
  return { width: b.readUInt32BE(16), height: b.readUInt32BE(20), colorType: b[25] };
}

test('manifest makes an installable standalone app', () => {
  assert.equal(manifest.display, 'standalone');
  assert.equal(manifest.start_url, '/');
  assert.equal(manifest.scope, '/');
  assert.ok(manifest.name && manifest.short_name && manifest.short_name.length <= 12);
  assert.match(manifest.theme_color, /^#[0-9A-Fa-f]{6}$/);
  assert.match(manifest.background_color, /^#[0-9A-Fa-f]{6}$/);
});

test('manifest icons exist at their declared sizes (192 + 512 any, 512 maskable)', () => {
  for (const icon of manifest.icons) {
    const file = `public${icon.src}`;
    assert.ok(existsSync(resolve(root, file)), `${file} missing`);
    if (icon.type !== 'image/png') continue;
    const [w, h] = icon.sizes.split('x').map(Number);
    const info = pngInfo(file);
    assert.deepEqual([info.width, info.height], [w, h], `${file} size`);
  }
  const png = manifest.icons.filter((i) => i.type === 'image/png');
  assert.ok(png.some((i) => i.sizes === '192x192' && i.purpose === 'any'));
  assert.ok(png.some((i) => i.sizes === '512x512' && i.purpose === 'any'));
  assert.ok(png.some((i) => i.sizes === '512x512' && i.purpose === 'maskable'));
});

test('apple-touch-icon is 180px and opaque (iOS fills transparency with black)', () => {
  const info = pngInfo('public/apple-touch-icon.png');
  assert.deepEqual([info.width, info.height], [180, 180]);
  assert.equal(info.colorType, 2, 'expected RGB without alpha');
});

test('index.html links the manifest, touch icon and Home Screen meta', () => {
  assert.match(html, /<link rel="manifest" href="\/manifest\.webmanifest"/);
  assert.match(html, /<link rel="apple-touch-icon" href="\/apple-touch-icon\.png"/);
  assert.match(html, /<link rel="icon" href="\/favicon\.svg"/);
  assert.match(html, /viewport-fit=cover/);
  assert.match(html, /<meta name="theme-color" content="#[0-9A-Fa-f]{6}"/);
  assert.match(html, /<meta name="apple-mobile-web-app-capable" content="yes"/);
  assert.match(html, /<meta name="apple-mobile-web-app-title" content="Goblin"/);
});

test('ROOM_PAGE in index.html is each room\'s swatch[0] (what applyRoom sets as theme-color)', () => {
  const block = html.match(/var ROOM_PAGE = (\{[^}]*\});/);
  assert.ok(block, 'ROOM_PAGE missing');
  const roomPage = Function(`return ${block[1]}`)();
  const modes = Function(`return ${html.match(/var ROOM_MODES = (\{[^}]*\});/)[1]}`)();
  assert.deepEqual(Object.keys(roomPage).sort(), Object.keys(modes).sort());

  const src = read('src/data/palettes.ts');
  const swatches = {};
  for (const m of src.matchAll(/id: '([a-z-]+)',[\s\S]*?swatch: \['(#[0-9A-Fa-f]{6})'/g)) swatches[m[1]] = m[2];
  assert.deepEqual(roomPage, swatches);
});
